head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnEnableColumn]<br/>Body Column 정보를 사용하여 특정 Column 에 바인딩된 특정 아이템의 비활성화 여부를 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 특정 아이템을 비활성화 하려는 Body Column 의 ID 를 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 테스트 참고 라벨 (가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] grade 는 select 컬럼, 아이템 소스 DataList(dlt_grade) 는 enable_info 컬럼 보유. enable_info 가 기준값과 일치하면 비활성.\n[절차] columnInfo 에 컬럼 ID(grade) 선택 후 (setColumnEnableColumn 실행).\n[확인] enableColumnFalseValue(F,0) 와 일치하는 아이템은 비활성, 나머지는 활성."', '', 'label1');

    // GridView 본문 컬럼 DataList (grade 는 select 로 구성)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="text"></w2:column>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    dlt_bind.setJSON([
        { "name": "노트북", "grade": "A", "amount": "1200", "region": "서울" },
        { "name": "모니터", "grade": "B", "amount": "1800", "region": "부산" },
        { "name": "키보드", "grade": "C", "amount": "900",  "region": "대전" },
        { "name": "마우스", "grade": "A", "amount": "500",  "region": "광주" }
    ], false);

    // grade select 컬럼 옵션 DataList (label / value / enable_info) - itemset 바인딩용
    //  enable_info 가 비활성 정보값 컬럼. setColumnEnableColumn 의 falseValue(F,0) 와 일치하면 비활성.
    let strOpt = '';
    strOpt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strOpt += '<w2:columnInfo>';
    strOpt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strOpt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strOpt += '<w2:column id="enable_info" name="enable_info" dataType="text"></w2:column>';
    strOpt += '</w2:columnInfo>';
    strOpt += '<w2:data use="true"></w2:data>';
    strOpt += '</w2:dataList>';
    $p.data.create(strOpt);

    dlt_grade.setJSON([
        { "label": "A등급", "value": "A", "enable_info": "Y" },
        { "label": "B등급", "value": "B", "enable_info": "F" },
        { "label": "C등급", "value": "C", "enable_info": "0" }
    ], false);

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (grade 컬럼 inputType=select + 옵션 DataList dlt_grade 바인딩 itemset)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:560px;height:220px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol1" value="품목"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol2" value="등급"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol3" value="단가"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="지역"></w2:column>';
    strTarget += '<\/w2:row>';
    strTarget += '<\/w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // grade - select 컬럼 (옵션 DataList dlt_grade 바인딩 itemset)
    strTarget += '<w2:column width="140" style="" inputType="select" id="grade" dataList="grade">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_grade">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '<\/w2:itemset>';
    strTarget += '<\/w2:choices>';
    strTarget += '<\/w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="amount" dataList="amount"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="region" dataList="region"></w2:column>';
    strTarget += '<\/w2:row>';
    strTarget += '<\/w2:gBody>';
    strTarget += '<\/w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// setColumnEnableColumn 실행 : 컬럼 ID 로 특정 아이템 비활성화 여부 설정
//  -> 첫 인자에 컬럼 ID 문자열(grade) 전달. 인덱스 대신 ID 로 설정.
scwin.btn_setColumnEnableColumn_onclick = function () {
    let columnInfo = par_columnInfo.getText();   // 컬럼 ID 그대로 전달 (Number 변환 금지)
    let enableColumnId = "enable_info";
    let falseValue = "F,0";

    // 컬럼 ID 로 enable_info 가 F 또는 0 인 아이템을 드롭다운에서 비활성화
    target1.setColumnEnableColumn(columnInfo, enableColumnId, falseValue);

    // 설정 확인 : 해당 컬럼 select 의 itemArr (활성/비활성 아이템 라벨 목록)
    let colIndex = target1.getColumnIndex(columnInfo);

    // select 객체는 셀이 편집모드일 때 인스턴스화되므로, Row 0 의 grade 셀을 편집모드로 전환하여 itemArr 확인
    let editTd = document.querySelector("td[id*='target1_cell_0_" + colIndex + "']");
    if (editTd) {
        target1.setEditMode(editTd);
    }

    let cellInfo = target1.getCellInfo(colIndex);
    let enabledLabels = [];
    let disabledLabels = [];
    if (cellInfo && cellInfo.select && cellInfo.select.itemArr) {
        let itemArr = cellInfo.select.itemArr;
        for (let i = 0; i < itemArr.length; i++) {
            if (itemArr[i]._disabled === true) {
                disabledLabels.push(itemArr[i].label);
            } else {
                enabledLabels.push(itemArr[i].label);
            }
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue("setColumnEnableColumn('" + columnInfo + "', '" + enableColumnId + "', '" + falseValue + "') -> 활성 아이템 : [" + enabledLabels.join(", ") + "] / 비활성 아이템(enable_info=F 또는 0) : [" + disabledLabels.join(", ") + "]");
}
